const pieceName:Record<string,string>={p:'Piyon',n:'At',b:'Fil',r:'Kale',q:'Vezir',k:'Şah'};
const values:Record<string,number>={p:100,n:320,b:330,r:500,q:900,k:0};

type Snapshot={fen:string;beforeFen:string;move:Move;eval:number;turn:'w'|'b';engineEval?:number;beforeEngineEval?:number;bestMove?:string|null;depth?:number};
function formatTime(sec:number){const m=Math.floor(sec/60).toString().padStart(2,'0'); const s=(sec%60).toString().padStart(2,'0'); return `${m}:${s}`;}
function materialEval(g:Chess){let score=0; for(const row of g.board())for(const p of row)if(p)score+=(p.color==='w'?1:-1)*values[p.type]; return score;}
function labelLoss(loss:number){if(loss>=250)return {label:'Büyük hata',tone:'bad'};if(loss>=100)return {label:'Hata',tone:'bad'};if(loss>=45)return {label:'Şüpheli',tone:'warn'};return {label:'İyi',tone:'good'};}
function snapshotsFromHistory(items:any[]):Snapshot[]{const g=new Chess();const out:Snapshot[]=[];for(const item of items){try{const move=g.move({from:item.from,to:item.to,promotion:item.promotion||undefined});if(move){const beforeFen=(()=>{const c=new Chess();for(const prior of out.map(x=>x.move))c.move({from:prior.from,to:prior.to,promotion:prior.promotion});return c.fen();})();out.push({fen:g.fen(),beforeFen,move,eval:materialEval(g),turn:move.color});}}catch{}}return out;}
