const enableBrowserPush=async()=>{ try{ if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))return; const cfg=await fetch('/api/push/config').then(r=>r.json()); if(!cfg.enabled||!cfg.publicKey)return; const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission(); if(permission!=='granted')return; const reg=await navigator.serviceWorker.register('/public-sw.js'); let sub=await reg.pushManager.getSubscription(); if(!sub) sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(atob(String(cfg.publicKey).replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))}); await fetch('/api/push/subscribe',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(sub.toJSON())}); }catch{} };
